window.kbPageData["views/entry/k-cdf583495ea95878"] = {"key":"entry/k-cdf583495ea95878","state":{"route":"entry/k-cdf583495ea95878"},"node":{"id":"k-cdf583495ea95878","mode":"k","title":"两期比值的增减判定","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["分子和分母均为正时，分子增速大于分母增速则两者的比值上升"],"qs":["国考 2024 地市级 行测#122"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"当分子和分母在基期、现期均为正时，两者采用同一基期计算增长率。分子增速大于分母增速，比值上升；两者增速相等，比值不变；分子增速小于分母增速，比值下降。","review":{"definition":"当分子和分母在基期、现期均为正时，两者采用同一基期计算增长率。分子增速大于分母增速，比值上升；两者增速相等，比值不变；分子增速小于分母增速，比值下降。","explanation":"现期比值与基期比值之比等于（1＋分子增速）÷（1＋分母增速）。第122题的单位面积产量等于产量除以播种面积。2018、2020、2021、2022年均为产量同比增加、播种面积同比减少，单位面积产量随之上升。2019年产量由1798万吨降至1778万吨，同比下降约1.11%，播种面积由476万公顷降至467万公顷，同比下降约1.89%。产量降幅更小，单位面积产量也同比上升。因此共有5个年份，选D。","references":[],"evidence":"当分子增速（a）大于分母增速（b）时，平均数上升","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2024 地市级 行测#122":{"paper":"国考 2024 地市级 行测","n":122,"mod":"资料分析","src":["92d0b72e86a6a33d568d.pdf",25],"asrc":["e1792c53900a45f1b9fa.pdf",40],"card":"f6877d5a60aefec584bb2ddd","links":[{"id":"k-cdf583495ea95878","role":"解题依据","why":"比较产量与播种面积的同比增速即可判断单位面积产量是否增长。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-cdf583495ea95878":[["国考 2024 地市级 行测#122"]]}};
